const pricingAdminState={newId:'__new_product_pricing__'};
const pricingMoney=cents=>(Number(cents||0)/100).toFixed(2);
const pricingVariant=variant=>{const base=Number(variant.price_cents||0),cash=Number(variant.cash_price_cents??base),promo=variant.promo_price_cents==null?null:Number(variant.promo_price_cents);return {base,cash,promo}};
function enhancePricingRows(){const editor=document.querySelector('#product-editor');if(!editor)return;editor.querySelectorAll('.variant-row').forEach(row=>{if(row.dataset.pricingReady)return;const saved=adminState.selected?.product_variants?.find(variant=>variant.id&&variant.id===row.dataset.id);const full=Number(saved?.price_cents||row.querySelector('.variant-price')?.value*100||0);const cash=Number(saved?.cash_price_cents??full);const promo=saved?.promo_price_cents==null?'':Number(saved.promo_price_cents)/100;const stock=row.querySelector('.variant-stock')?.closest('label');stock?.insertAdjacentHTML('beforebegin',`<label>Preço à vista (R$)<input class="variant-cash-price" type="number" min="0" step="0.01" required value="${pricingMoney(cash)}"></label><label>Promoção à vista (R$)<input class="variant-promo-price" type="number" min="0" step="0.01" value="${promo}"><small>Opcional</small></label>`);row.dataset.pricingReady='true'})}
const pricingObserver=new MutationObserver(enhancePricingRows);pricingObserver.observe(document.querySelector('#product-editor'),{childList:true,subtree:true});
const originalPricingLoad=loadProducts;loadProducts=async function(){const select='id,brand,name,subcategory,description,image_url,image_override_url,active,product_variants(id,name,price_cents,cash_price_cents,promo_price_cents,stock_quantity,active)';adminState.products=await request('/rest/v1/products?select='+encodeURIComponent(select)+'&order=name.asc');renderList();if(adminState.selected){const fresh=adminState.products.find(item=>item.id===adminState.selected.id);if(fresh)selectProduct(fresh)}enhancePricingRows()};
const pricingButton=document.querySelector('#new-product');if(pricingButton)pricingButton.onclick=()=>selectProduct({id:pricingAdminState.newId,brand:'',name:'',subcategory:adminState.products.find(product=>product.active)?.subcategory||'',description:'',image_url:null,image_override_url:null,active:true,product_variants:[]});
document.querySelector('#product-editor').addEventListener('submit',async event=>{const product=adminState.selected;if(!product||product.id!==pricingAdminState.newId)return;event.preventDefault();event.stopImmediatePropagation();const form=event.currentTarget,note=document.querySelector('#editor-message');note.className='admin-message';note.textContent='Criando produto...';try{const productPayload={brand:document.querySelector('#product-brand').value.trim(),name:document.querySelector('#product-name').value.trim(),category:'Estética Automotiva',subcategory:document.querySelector('#product-category').value.trim(),description:document.querySelector('#product-description').value.trim()||null,active:document.querySelector('#product-active').checked};const rows=[...form.querySelectorAll('.variant-row')];if(!productPayload.brand||!productPayload.name||!productPayload.subcategory||!rows.length)throw new Error('Preencha marca, nome, categoria e pelo menos uma variação.');const variants=rows.map(row=>({name:row.querySelector('.variant-name').value.trim(),price_cents:Math.round(Number(row.querySelector('.variant-price').value)*100),cash_price_cents:Math.round(Number(row.querySelector('.variant-cash-price').value)*100),promo_price_cents:row.querySelector('.variant-promo-price').value===''?null:Math.round(Number(row.querySelector('.variant-promo-price').value)*100),stock_quantity:row.querySelector('.variant-stock').value===''?null:Math.max(0,Math.floor(Number(row.querySelector('.variant-stock').value))),active:row.querySelector('.variant-active').checked}));if(variants.some(variant=>!variant.name||Number.isNaN(variant.price_cents)||Number.isNaN(variant.cash_price_cents)||variant.price_cents<0||variant.cash_price_cents<0||(variant.promo_price_cents!=null&&(Number.isNaN(variant.promo_price_cents)||variant.promo_price_cents<0||variant.promo_price_cents>=variant.cash_price_cents))))throw new Error('Confira os preços: a promoção deve ser menor que o preço à vista.');const created=await request('/rest/v1/products',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(productPayload)});const createdProduct=Array.isArray(created)?created[0]:created;if(!createdProduct?.id)throw new Error('O produto foi criado, mas não foi possível obter seu identificador.');const imageUrl=await uploadPhoto(document.querySelector('#product-image').files[0],createdProduct.id);if(imageUrl)await request('/rest/v1/products?id=eq.'+encodeURIComponent(createdProduct.id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({image_override_url:imageUrl})});for(const variant of variants)await request('/rest/v1/product_variants',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({...variant,product_id:createdProduct.id})});note.textContent='Produto criado com sucesso.';await loadProducts();selectProduct(adminState.products.find(item=>item.id===createdProduct.id))}catch(error){note.classList.add('error');note.textContent=error.message}},true);
document.querySelector('#product-editor').addEventListener('submit',async event=>{const product=adminState.selected;if(!product||product.id===pricingAdminState.newId)return;event.preventDefault();event.stopImmediatePropagation();const form=event.currentTarget,note=document.querySelector('#editor-message');note.className='admin-message';note.textContent='Salvando...';try{const imageUrl=await uploadPhoto(document.querySelector('#product-image').files[0],product.id);const update={brand:document.querySelector('#product-brand').value.trim(),name:document.querySelector('#product-name').value.trim(),subcategory:document.querySelector('#product-category').value.trim(),description:document.querySelector('#product-description').value.trim()||null,active:document.querySelector('#product-active').checked};if(imageUrl)update.image_override_url=imageUrl;for(const removedId of adminState.removedVariantIds)await request('/rest/v1/product_variants?id=eq.'+encodeURIComponent(removedId),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({active:false})});await request('/rest/v1/products?id=eq.'+encodeURIComponent(product.id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(update)});for(const row of form.querySelectorAll('.variant-row')){const payload={product_id:product.id,name:row.querySelector('.variant-name').value.trim(),price_cents:Math.round(Number(row.querySelector('.variant-price').value)*100),cash_price_cents:Math.round(Number(row.querySelector('.variant-cash-price').value)*100),promo_price_cents:row.querySelector('.variant-promo-price').value===''?null:Math.round(Number(row.querySelector('.variant-promo-price').value)*100),stock_quantity:row.querySelector('.variant-stock').value===''?null:Math.max(0,Math.floor(Number(row.querySelector('.variant-stock').value))),active:row.querySelector('.variant-active').checked};if(!payload.name||Number.isNaN(payload.price_cents)||Number.isNaN(payload.cash_price_cents)||payload.price_cents<0||payload.cash_price_cents<0||(payload.promo_price_cents!=null&&(Number.isNaN(payload.promo_price_cents)||payload.promo_price_cents<0||payload.promo_price_cents>=payload.cash_price_cents)))throw new Error('Confira os preços: a promoção deve ser menor que o preço à vista.');const id=row.dataset.id;if(id)await request('/rest/v1/product_variants?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(payload)});else await request('/rest/v1/product_variants?on_conflict=product_id,name',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(payload)})}note.textContent='Alterações salvas com sucesso.';await loadProducts()}catch(error){note.classList.add('error');note.textContent=error.message}},true);
if(adminState.session)loadProducts();
